const moneyShort=v=>{const n=Number(v||0);if(!Number.isFinite(n)||n===0)return "$0.00";return `$${n.toFixed(Math.min(8,Math.max(2,Math.ceil(Math.abs(Math.log10(n)))+2)))}`};
const pct=v=>`${Number(v||0).toFixed(2)}%`;
